-- Messrunde 10c-4a -- Sitzung 0: Rahmen, Bestand, Vergleichsanker, Belegungsprobe
-- Auftrag:  "Prozessansicht -- freies Zeitfenster, Messrunde (Schritt 10c-4a)",
--           Stand 07.09.2026
-- Ergebnis: docs/process-view.md Paragraf 30 ff.
--
-- ERZEUGT von scripts/messung-prozessansicht-frei/erzeuge.py. Der Statementtext
-- kommt aus scripts/messung-prozessansicht/gerendert.txt (M116, aus
-- ProzessbaumRepository gefallen) und ist NUR in Ebene und Bereichspraedikat
-- variiert.
--
-- Ausschliesslich SELECT / SET / EXPLAIN. (Regel S1) Benutzer monitor_read.
-- G1: keine Zugangsdaten, kein Hostname. Mandanten-IDs sind Codes.
-- L9: SET max_statement_time = 60. Jedes Statement, das die Grenze reisst, ist
--     eine Abweichung vom Rahmen und wird als solche ausgewiesen.
--
-- Z1: Alle Fenster enden auf 2025-12-30 03:00:00 -- unterhalb des Dev-Ankers
--     2025-12-30 04:09:47, auf einer Stundengrenze, im dichten Bestand.
--
-- ZWECK. Drei Dinge, bevor gemessen wird:
--   1. Der Bestand der drei Ebenen -- sind es die Zahlen aus rollup.md?
--   2. Der Vergleichsanker: M116 NEXANS 48H (6,781 ms) und 12M (75,743 ms)
--      wiederholt. Eine Abweichung ueber 25 % wird ausgewiesen, nicht
--      weggerechnet -- dann ist diese Sitzung mit M116 nicht vergleichbar.
--   3. Die Belegungsprobe: je Fenster und Ebene COUNT(*) und SUM(anzahl),
--      mandantenfrei -- die Zeilenzahl, die der Bereichszugriff liest, und
--      gegen die die Laufzeiten normiert werden.

SELECT '=== 00 read_only (erste Abfrage der Sitzung) ===' AS marke;
SELECT @@global.read_only AS read_only, NOW() AS serverzeit, VERSION() AS version,
       @@max_statement_time AS grenze_vorher;

SET max_statement_time = 60;
SET profiling = 1;
SET profiling_history_size = 100;

SELECT '=== 01 Bestand der drei Ebenen ===' AS marke;
SELECT 'stunde' AS ebene, COUNT(*) AS zeilen, SUM(anzahl) AS nachrichten, MIN(stunde) AS erster, MAX(stunde) AS letzter FROM overlord_monitor.message_rollup
UNION ALL SELECT 'tag', COUNT(*), SUM(anzahl), MIN(tag), MAX(tag) FROM overlord_monitor.message_rollup_tag
UNION ALL SELECT 'monat', COUNT(*), SUM(anzahl), MIN(monat), MAX(monat) FROM overlord_monitor.message_rollup_monat;

SELECT '=== 02 Vergleichsanker: M116 wiederholt, Zeichen fuer Zeichen ===' AS marke;
SELECT '=== M116-REPRO-NEXANS-48H · Plan (Regel L15) ===' AS marke;
EXPLAIN select `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`, sum(`overlord_monitor`.`message_rollup`.`anzahl`) from `overlord_monitor`.`message_rollup` where (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-12-28 05:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2025-12-30 05:00:00.0' and exists (select 1 as `one` from `GlassfishDB`.`Process` as `baum_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `baum_process`.`ProjectID` where (`baum_process`.`ProcessID` = `overlord_monitor`.`message_rollup`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS'))) group by `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`;
SELECT '=== M116-REPRO-NEXANS-48H · sechs Laeufe ===' AS marke;
SELECT MAX(QUERY_ID) INTO @basis FROM information_schema.PROFILING;
