select `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`, sum(`overlord_monitor`.`message_rollup`.`anzahl`) from `overlord_monitor`.`message_rollup` where (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-12-28 05:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2025-12-30 05:00:00.0' and exists (select 1 as `one` from `GlassfishDB`.`Process` as `baum_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `baum_process`.`ProjectID` where (`baum_process`.`ProcessID` = `overlord_monitor`.`message_rollup`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS'))) group by `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`;
select `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`, sum(`overlord_monitor`.`message_rollup`.`anzahl`) from `overlord_monitor`.`message_rollup` where (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-12-28 05:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2025-12-30 05:00:00.0' and exists (select 1 as `one` from `GlassfishDB`.`Process` as `baum_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `baum_process`.`ProjectID` where (`baum_process`.`ProcessID` = `overlord_monitor`.`message_rollup`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS'))) group by `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`;
select `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`, sum(`overlord_monitor`.`message_rollup`.`anzahl`) from `overlord_monitor`.`message_rollup` where (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-12-28 05:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2025-12-30 05:00:00.0' and exists (select 1 as `one` from `GlassfishDB`.`Process` as `baum_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `baum_process`.`ProjectID` where (`baum_process`.`ProcessID` = `overlord_monitor`.`message_rollup`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS'))) group by `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`;
SELECT 'M116-REPRO-NEXANS-48H' AS fall,
       COUNT(*)                          AS anzahl_laeufe,
       MAX(CASE WHEN rn = 1 THEN ms END) AS aufwaermlauf,
       MIN(CASE WHEN rn > 1 THEN ms END) AS beste_von_fuenf,
       GROUP_CONCAT(CASE WHEN rn > 1 THEN ms END ORDER BY rn) AS alle_fuenf
FROM (SELECT ROW_NUMBER() OVER (ORDER BY QUERY_ID) AS rn,
             ROUND(SUM(DURATION) * 1000, 3) AS ms
      FROM information_schema.PROFILING
      WHERE QUERY_ID > @basis + 1
      GROUP BY QUERY_ID) t;

